195	
196	    public void addPet(Pet pet) {
197	        getPetsInternal().add(pet);
198	        pet.setOwner(this);
199	    }
200	
201	    /**
202	     * Return the Pet with the given name, or null if none found for this Owner.
203	     *
204	     * @param name to test
205	     * @return true if pet name is already in use
206	     */
207	    public Pet getPet(String name) {
208	        return getPet(name, false);
209	    }
210	
211	    /**
212	     * Return the Pet with the given name, or null if none found for this Owner.
213	     *
214	     * @param name to test
215	     * @return true if pet name is already in use
216	     */
217	    public Pet getPet(String name, boolean ignoreNew) {
218	        name = name.toLowerCase();
219	        for (Pet pet : getPetsInternal()) {
220	            if (!ignoreNew || !pet.isNew()) {
221	                String compName = pet.getName();
222	                compName = compName.toLowerCase();
223	                if (compName.equals(name)) {
224	                    return pet;
225	                }
226	            }
227	        }
228	        return null;
229	    }
230	
231	    public Pet getPet(Integer petId) {
232	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
233	    }
234	
235	    @Override
236	    public String toString() {
237	        return new ToStringCreator(this)
238	
239	            .append("id", this.getId())
240	            .append("new", this.isNew())
241	            .append("lastName", this.getLastName())
242	            .append("firstName", this.getFirstName())
243	            .append("address", this.address)
244	            .append("city", this.city)
245	            .append("telephone", this.telephone)
246	            .toString();
247	    }
248	}
